const webhook = $input.first().json;
const cfg = $('Set config').item.json;

// Extract meeting ID from Fireflies webhook
// Fireflies sends meetingId in the body
const meetingId = webhook.meetingId || webhook.id || webhook.transcriptId || '';
const eventType = webhook.eventType || webhook.event_type || 'Transcription completed';

if (!meetingId) {
  throw new Error('No meeting ID in webhook payload. Check Fireflies webhook configuration. Received: ' + JSON.stringify(webhook));
}

return [{
  json: {
    meetingId,
    eventType,
    receivedAt: new Date().toISOString(),
    firefliesApiKey: cfg.firefliesApiKey,
    clickupApiKey: cfg.clickupApiKey,
    clickupListId: cfg.clickupListId,
    managerEmail: cfg.managerEmail,
    slackChannelId: cfg.slackChannelId,
    sheetId: cfg.sheetId,
    sheetName: cfg.sheetName,
    teamName: cfg.teamName,
    senderName: cfg.senderName
  }
}];

