={
  "query": "query GetTranscript($id: String!) { transcript(id: $id) { id title date duration participants host_email video_url sentences { speaker_name text ai_filters { task pricing question } } summary { overview keywords action_items bullet_gist } analytics { sentiments { positive_pct neutral_pct negative_pct } speakers { name duration_pct word_count questions longest_monologue } } } }",
