parameters.jsCode:
const response = $input.first().json;
const cfg = $('Get the meeting ID').item.json;

const transcript = response?.data?.transcript;

if (!transcript) {
  throw new Error('Fireflies transcript not found. The transcript may still be processing. Meeting ID: ' + cfg.meetingId);
}

// Build full readable transcript with speaker labels
const sentences = transcript.sentences || [];
const fullText = sentences
  .map(s => s.speaker_name + ': ' + s.text)
  .join('\n')
  .substring(0, 6000);

// Identify sentences that mention pricing or budget
const pricingSentences = sentences
  .filter(s => s.ai_filters?.pricing)
  .map(s => s.text);

// Identify questions asked
const questionSentences = sentences
  .filter(s => s.ai_filters?.question)
  .map(s => s.speaker_name + ' asked: ' + s.text);

// Speaker analytics
const speakers = (transcript.analytics?.speakers || []).map(s => ({
  name: s.name,
  talkPercent: Math.round(s.duration_pct || 0),
  wordCount: s.word_count || 0,
  questions: s.questions || 0
}));

// Sentiment
const sentiments = transcript.analytics?.sentiments || {};
const positivePct = Math.round(sentiments.positive_pct || 0);
const negativePct = Math.round(sentiments.negative_pct || 0);
const neutralPct = Math.round(sentiments.neutral_pct || 0);

let sentimentLabel = 'Neutral';
if (negativePct > 30) sentimentLabel = 'Negative';
else if (negativePct > 15) sentimentLabel = 'Mixed';
else if (positivePct > 60) sentimentLabel = 'Positive';

const durationMin = Math.round((transcript.duration || 0) / 60);

// Format date nicely
const meetingDate = transcript.date
  ? new Date(transcript.date).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
  : 'Unknown date';

return [{
  json: {
    meetingId: transcript.id,
    meetingTitle: transcript.title || 'Untitled Meeting',
    meetingDate,
    durationMin,
    participants: (transcript.participants || []).join(', '),
    hostEmail: transcript.host_email || '',
    videoUrl: transcript.video_url || '',
    fullText,
    pricingSentences,
    hasPricingSignal: pricingSentences.length > 0,
    questionSentences,
    speakers,
    positivePct,
    neutralPct,
    negativePct,
    sentimentLabel,
    aiOverview: transcript.summary?.overview || '',
    aiKeywords: (transcript.summary?.keywords || []).join(', '),
    aiActionItems: transcript.summary?.action_items || '',
    aiBullets: transcript.summary?.bullet_gist || '',
    // Carry config
    firefliesApiKey: cfg.firefliesApiKey,
    clickupApiKey: cfg.clickupApiKey,
    clickupListId: cfg.clickupListId,
    managerEmail: cfg.managerEmail,
    slackChannelId: cfg.slackChannelId,
    sheetId: cfg.sheetId,
    sheetName: cfg.sheetName,
    teamName: cfg.teamName,
    senderName: cfg.senderName
  }
}];

const intel = $input.first().json.output;
const meetingData = $('Tidy the transcript').item.json;

if (!intel) {
  throw new Error('AI intelligence extraction failed. Check your OpenAI credential.');
}

const actionItems = intel.actionItems || [];
const sentiment = intel.sentimentAnalysis || {};
const competitors = intel.competitorsMentioned || [];

// Format action items for ClickUp task description
const actionItemsFormatted = actionItems.length > 0
  ? actionItems.map((item, i) =>
      (i + 1) + '. ' + item.task +
      '\n   Owner: ' + item.owner +
      ' | Priority: ' + item.priority +
      (item.deadline ? ' | By: ' + item.deadline : '')
    ).join('\n\n')
  : 'No action items identified in this meeting.';

// Format concerns for Sheets and email
const concernsList = (sentiment.concernsRaised || []).join(' | ') || 'None identified';
const positivesList = (sentiment.positives || []).join(' | ') || 'None identified';
const keyTopicsList = (intel.keyTopics || []).join(', ');
const competitorsList = competitors.join(', ') || 'None mentioned';

// ClickUp task fields
const clickupTaskTitle = '[Meeting] ' + meetingData.meetingTitle + ' — ' + meetingData.meetingDate;
const clickupTaskDescription =
  'Meeting: ' + meetingData.meetingTitle + '\n' +
  'Date: ' + meetingData.meetingDate + '\n' +
  'Duration: ' + meetingData.durationMin + ' minutes\n' +
  'Participants: ' + meetingData.participants + '\n' +
  'Sentiment: ' + (sentiment.overallSentiment || 'Unknown') + '\n' +
  'Success Score: ' + (intel.meetingSuccessScore || 0) + ' out of 10\n\n' +
  'ACTION ITEMS:\n' + actionItemsFormatted + '\n\n' +
  'KEY TOPICS:\n' + keyTopicsList + '\n\n' +
  (meetingData.videoUrl ? 'Recording: ' + meetingData.videoUrl : '');

// Priority for ClickUp (based on sentiment and success score)
let clickupPriority = 2; // normal
if (sentiment.overallSentiment === 'Negative') clickupPriority = 1; // urgent
else if (intel.meetingSuccessScore >= 8) clickupPriority = 3; // low

const loggedAt = new Date().toISOString().replace('T', ' ').substring(0, 16);

// Flag for routing
const needsManagerAlert =
  sentiment.overallSentiment === 'Negative' ||
  sentiment.overallSentiment === 'Mixed';

return [{
  json: {
    ...meetingData,
    actionItems,
    actionItemsFormatted,
    actionItemCount: actionItems.length,
    sentiment,
    overallSentiment: sentiment.overallSentiment || 'Unknown',
    clientMood: sentiment.clientMood || '',
    concernsList,
    positivesList,
    keyTopics: intel.keyTopics || [],
    keyTopicsList,
    competitors,
    competitorsList,
    hasCompetitorMention: intel.hasCompetitorMention || false,
    nextMeetingNeeded: intel.nextMeetingNeeded || false,
    meetingSuccessScore: intel.meetingSuccessScore || 0,
    needsManagerAlert,
    clickupTaskTitle,
    clickupTaskDescription,
    clickupPriority,
    loggedAt
  }
}];

