const summaryText = $input.first().json.output || 'Meeting summary could not be generated. Please review the transcript manually.';
const d = $('Prepare the deliverables').item.json;

// Gmail summary email
const emailSubject = 'Meeting Summary — ' + d.meetingTitle + ' — ' + d.meetingDate;
const emailBody = summaryText;

// Slack team debrief message
const slackMsg =
  'Meeting debrief: ' + d.meetingTitle + '\n' +
  'Date: ' + d.meetingDate + ' | Duration: ' + d.durationMin + ' min\n' +
  'Participants: ' + d.participants + '\n' +
  'Sentiment: ' + d.overallSentiment + ' | Score: ' + d.meetingSuccessScore + '/10\n\n' +
  'Action items: ' + d.actionItemCount + '\n' +
  d.actionItems.slice(0, 3).map((a, i) => (i + 1) + '. ' + a.task + ' — ' + a.owner).join('\n') +
  (d.actionItemCount > 3 ? '\n... and ' + (d.actionItemCount - 3) + ' more in ClickUp' : '') + '\n\n' +
  'Key topics: ' + d.keyTopicsList +
  (d.hasCompetitorMention ? '\n\nCompetitor mentioned: ' + d.competitorsList : '') +
  (d.videoUrl ? '\n\nRecording: ' + d.videoUrl : '');

// Manager alert email (for negative sentiment)
const managerEmailBody =
  'Hi,\n\nThis is an automated flag from your meeting intelligence system.\n\n' +
  'Meeting: ' + d.meetingTitle + '\n' +
  'Date: ' + d.meetingDate + '\n' +
  'Participants: ' + d.participants + '\n' +
  'Sentiment detected: ' + d.overallSentiment + '\n' +
  'Success score: ' + d.meetingSuccessScore + ' out of 10\n\n' +
  'Client mood: ' + d.clientMood + '\n\n' +
  'Concerns raised by client:\n' +
  (d.sentiment?.concernsRaised || []).map((c, i) => (i + 1) + '. ' + c).join('\n') + '\n\n' +
  'Recommended action: Review the meeting recording and follow up with the client within 24 hours.\n\n' +
  (d.videoUrl ? 'Recording: ' + d.videoUrl + '\n\n' : '') +
  'Best regards,\n' + d.teamName + ' Meeting Intelligence';

// Competitor alert email
const competitorEmailBody =
  'Hi,\n\nA competitor was mentioned during a recent client meeting.\n\n' +
  'Meeting: ' + d.meetingTitle + '\n' +
  'Date: ' + d.meetingDate + '\n' +
  'Client: ' + d.participants + '\n' +
  'Competitors mentioned: ' + d.competitorsList + '\n\n' +
  'Key topics in this meeting: ' + d.keyTopicsList + '\n\n' +
  'Recommended action: Research the mentioned competitors and prepare a comparison document before the next client interaction.\n\n' +
  (d.videoUrl ? 'Recording: ' + d.videoUrl + '\n\n' : '') +
  'Best regards,\n' + d.teamName + ' Meeting Intelligence';

return [{
  json: {
    ...d,
    emailSubject,
    emailBody,
    slackMsg,
    managerEmailBody,
    competitorEmailBody
  }
}];
